#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct DagStringEscape {
    pub spelled: i64,
    pub value: i64,
}

pub fn dag_string_escape_last() -> DagStringEscape {
    thread_local! {
        static CACHED: DagStringEscape = {
            serde_json::from_str("{\"spelled\": 125, \"value\": 125}")
                .expect("valid data definition")
        };
    }
    CACHED.with(|c: &DagStringEscape| c.clone())
}

pub fn dag_string_escape_leading() -> Rc<Vec<DagStringEscape>> {
    Rc::new(vec![DagStringEscape {
    spelled: 34,
    value: 34,
}, DagStringEscape {
    spelled: 92,
    value: 92,
}, DagStringEscape {
    spelled: 48,
    value: 0,
}, DagStringEscape {
    spelled: 110,
    value: 10,
}, DagStringEscape {
    spelled: 114,
    value: 13,
}, DagStringEscape {
    spelled: 116,
    value: 9,
}, DagStringEscape {
    spelled: 123,
    value: 123,
}])
}

pub fn dag_string_escapes() -> Rc<Vec<DagStringEscape>> {
    crate::std_algebra::list_append(dag_string_escape_leading(), Rc::new(vec![dag_string_escape_last()]))
}

pub fn dag_string_escape_char_pattern() -> Rc<LexPattern> {
    crate::std_algebra::fold_list(dag_string_escape_leading(), Rc::new(LexPattern::CharPattern {
    char: dag_string_escape_last().spelled.clone(),
}), |rest, row| Rc::new(LexPattern::ChoicePattern {
    left: Rc::new(LexPattern::CharPattern {
    char: row.spelled.clone(),
}),
    right: rest.clone(),
}))
}

