pub fn dag_token_class_emit_transforms() -> Rc<HashMap<Symbol, Rc<TokenClassEmitTransform>>> {
    crate::std_algebra::fold_list(crate::v2_std_compilers_lexing::lex_rule_set_matching_rules(dag_lex_rules()), v1_rt::rc_empty_map::<_, _>(), |acc, rule| match crate::v2_std_compilers_lexing::lex_rule_token_class_optional(rule) {
    Some(c) => v1_rt::rc_map_insert(acc, c.clone(), Rc::new(TokenClassEmitTransform::EmitSpellingWrap {
    prefix: "".to_string(),
    suffix: " ".to_string(),
})),
    std::option::Option::None => acc.clone(),
})
}

