pub fn dag_grammar_choice_of_production_names(names: Rc<Vec<Symbol>>) -> Rc<GrammarExpr> {
    { let __fm = names.clone(); if __fm.len() >= 1 { let first = (*__fm)[0].clone(); let rest: Rc<Vec<_>> = Rc::new(__fm.skip(1)); rest.iter().cloned().fold(dag_grammar_nonterminal(first.clone()), |acc: Rc<GrammarExpr>, name: Symbol| dag_grammar_choice(acc, dag_grammar_nonterminal(name.clone()))) } else { dag_grammar_nonterminal("dag_production_top_level_item".to_string()) } }
}

