pub fn emit_import_decl_emitted_node(qualified_name: Rc<Node>, import_block: Option<Rc<Node>>) -> Rc<Node> {
    {
        let prefix = Rc::new(vec![dag_surface_edge("dag_surface_import_decl".to_string(), dag_grammar_atom("dag_surface_import_decl".to_string())), dag_surface_edge("dag_surface_import_decl_qualified_name".to_string(), qualified_name)]);
Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Conj),
}),
    children: match import_block.clone() {
    Some(block) => crate::std_algebra::list_append(prefix.clone(), Rc::new(vec![dag_surface_edge("dag_surface_import_decl_block".to_string(), block.clone())])),
    std::option::Option::None => prefix.clone(),
},
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}
}

pub fn emit_row_import_decl(qualified_name: Rc<Node>, import_block: Option<Rc<Node>>) -> Rc<Node> {
    {
        let prefix = Rc::new(vec![emit_fixed_token("dag_token_kw_import".to_string()), qualified_name.clone()]);
emit_grammar_relation_row(dag_grammar_production("dag_production_import_decl".to_string(), dag_grammar_import_decl_expr(), "dag_surface_import_decl".to_string()), emit_import_decl_emitted_node(qualified_name.clone(), import_block.clone()), match import_block.clone() {
    Some(block) => crate::std_algebra::list_append(prefix.clone(), Rc::new(vec![block.clone()])),
    std::option::Option::None => prefix.clone(),
})
}
}

