pub fn dag_resolve_preserve_module_metadata_subtree(node: Rc<Node>) -> bool {
    match crate::v2_std_grammar::parse_production_emitted_identity_optional(node) {
    Some(id) => ((id.clone() == "dag_surface_module_header".to_string()) || (id.clone() == "dag_surface_qualified_name".to_string())),
    std::option::Option::None => false,
}
}

pub fn dag_node_is_module_root_conj(n: Rc<Node>) -> bool {
    match crate::v2_std_grammar::parse_production_emitted_identity_optional(n.clone()) {
    Some(id) => (id.clone() == "dag_surface_module".to_string()),
    std::option::Option::None => match (*n.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => n.children.clone().iter().cloned().fold(false, |found: bool, e: Rc<Edge>| (found || dag_surface_edge_is(e.clone(), "dag_surface_module_header".to_string()))),
    _ => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
},
}
}

