pub fn dag_kernel_value_type_binding(row: Rc<KernelValueType>) -> Option<std::string::String> {
    match (*row.value_type.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Atom { identity: _, .. }) => { let Connective::Atom { identity: id, .. } = __rc_connective.as_ref() else { unreachable!() }; crate::std_optional::optional_present(id.clone()) },
    _ => crate::std_optional::optional_absent(),
}
}

