pub fn dag_string_text_decoded(token_class: std::string::String, body: Option<String>, occurrence_id: Rc<NodeOccurrenceIdentity>) -> Rc<Outcome<String>> {
    {
        let escape_refusal = dag_string_text_refusal(token_class.clone(), "dag_string_literal_escape_malformed".to_string(), occurrence_id.clone());
match body.clone() {
    std::option::Option::None => dag_string_text_refusal(token_class.clone(), "dag_string_literal_lexeme_unframed".to_string(), occurrence_id.clone()),
    Some(text) => match (*crate::std_coercion::unicode_scalar_unfold(text.clone()).iter().cloned().fold(Rc::new(DagStringDecode::DagStringDecodeText {
    text: "".to_string(),
}), |st: Rc<DagStringDecode>, c: i64| dag_string_decode_step(st, c.clone()))).clone() {
    DagStringDecode::DagStringDecodeText { text: value, .. } => crate::v2_std_diagnostic::outcome_accepted(value.clone()),
    DagStringDecode::DagStringDecodeEscape { text: _, .. } => escape_refusal,
    DagStringDecode::DagStringDecodeHex { .. } => escape_refusal,
    DagStringDecode::DagStringDecodeUnicodeOpen { text: _, .. } => escape_refusal,
    DagStringDecode::DagStringDecodeUnicode { .. } => escape_refusal,
    DagStringDecode::DagStringDecodeMalformed { spelled: _, .. } => escape_refusal,
},
}
}
}

