#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum DagCanonicalLiteral {
    DagCanonicalBoolLiteral {
        value: bool,
    },
    DagCanonicalIntLiteral {
        magnitude: i64,
    },
    DagCanonicalSymbolLiteral {
        symbol: Symbol,
    },
    DagCanonicalStringLiteral {
        value: Symbol,
    },
    DagCanonicalFloatLiteral {
        lexeme: Symbol,
    },
}

pub fn dag_canonical_literal_shape_diagnostic(node: Rc<Node>) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: "dag_literal_shape_invalid".to_string(),
    at: crate::v2_std_diagnostic::node_locus(node),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})
}

pub fn dag_canonical_literal_from_node(node: Rc<Node>) -> Rc<Outcome<Rc<DagCanonicalLiteral>>> {
    match dag_symbol_literal_name_optional(node.clone()) {
    Some(name) => match crate::v2_std_grammar::node_atom_identity_optional(name.clone()) {
    Some(symbol) => crate::v2_std_diagnostic::outcome_accepted(Rc::new(DagCanonicalLiteral::DagCanonicalSymbolLiteral {
    symbol: symbol.clone(),
})),
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(dag_canonical_literal_shape_diagnostic(node.clone())),
},
    std::option::Option::None => if (crate::v2_std_grammar::node_atom_identity_optional(node.clone()) == crate::std_optional::optional_present("dag_token_string_literal".to_string())) {
        match dag_string_literal_value_symbol_optional(node.clone()) {
    Some(v) => crate::v2_std_diagnostic::outcome_accepted(Rc::new(DagCanonicalLiteral::DagCanonicalStringLiteral {
    value: v.clone(),
})),
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(dag_canonical_literal_shape_diagnostic(node.clone())),
}
    } else {
        if (dag_node_is_kw_true_atom(node.clone()) && (crate::std_algebra::length(node.children.clone()) == 0)) {
            crate::v2_std_diagnostic::outcome_accepted(Rc::new(DagCanonicalLiteral::DagCanonicalBoolLiteral {
    value: true,
}))
        } else {
            if (dag_node_is_kw_false_atom(node.clone()) && (crate::std_algebra::length(node.children.clone()) == 0)) {
                crate::v2_std_diagnostic::outcome_accepted(Rc::new(DagCanonicalLiteral::DagCanonicalBoolLiteral {
    value: false,
}))
            } else {
                if (dag_node_is_float_literal_atom(node.clone()) && (crate::std_algebra::length(node.children.clone()) == 1)) {
                    match dag_float_literal_lexeme_optional(node.clone()) {
    Some(l) => crate::v2_std_diagnostic::outcome_accepted(Rc::new(DagCanonicalLiteral::DagCanonicalFloatLiteral {
    lexeme: v1_rt::symbol_intern_lexeme(l.clone()),
})),
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(dag_canonical_literal_shape_diagnostic(node.clone())),
}
                } else {
                    if (dag_node_is_int_literal_atom(node.clone()) && (crate::std_algebra::length(node.children.clone()) == 1)) {
                        match (*dag_int_literal_magnitude_int_from_node(node.clone())).clone() {
    Outcome::Accepted { value: magnitude, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: Rc::new(DagCanonicalLiteral::DagCanonicalIntLiteral {
    magnitude: magnitude.clone(),
}),
    diagnostics: Box::new(d.clone()),
}) },
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_diagnostic::outcome_rejected(dag_canonical_literal_shape_diagnostic(node.clone())),
}
                    } else {
                        crate::v2_std_diagnostic::outcome_rejected(dag_canonical_literal_shape_diagnostic(node.clone()))
                    }
                }
            }
        }
    },
}
}

