pub fn dag_round_trip_lex_ready() -> bool {
    (((((((((((((dag_lex_token_symbol("dag_token_kw_module".to_string()) && dag_lex_token_symbol("dag_token_kw_import".to_string())) && dag_lex_token_symbol("dag_token_kw_alias".to_string())) && dag_lex_token_symbol("dag_token_kw_data".to_string())) && dag_lex_token_symbol("dag_token_kw_fn".to_string())) && dag_lex_token_symbol("dag_token_ident".to_string())) && dag_lex_token_symbol("dag_token_dot".to_string())) && dag_lex_token_symbol("dag_token_lbrace".to_string())) && dag_lex_token_symbol("dag_token_rbrace".to_string())) && dag_lex_token_symbol("dag_token_colon".to_string())) && dag_lex_token_symbol("dag_token_eq".to_string())) && dag_lex_token_symbol("dag_token_lparen".to_string())) && dag_lex_token_symbol("dag_token_rparen".to_string())) && dag_lex_token_symbol("dag_token_arrow".to_string()))
}

pub fn dag_round_trip_grammar_ready(lm: Rc<LanguageModel>) -> bool {
    ((((((crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_module".to_string()) && crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_module_header".to_string())) && crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_import_decl".to_string())) && crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_alias_decl".to_string())) && crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_data_decl".to_string())) && crate::v2_std_grammar::grammar_carries_symbol(lm.grammar.clone(), "dag_production_fn_decl".to_string())) && dag_grammar_top_level_item_standing_join())
}

pub fn dag_grammar_top_level_item_standing_join() -> bool {
    crate::std_algebra::fold_list(dag_grammar_top_level_item_productions(), true, |acc, production| (acc.clone() && match crate::v2_std_grammar::node_atom_identity_optional(production.emitted.clone()) {
    Some(id) => match crate::v2_extdeps_languages_dag_surface_item_standing::dag_surface_item_standing(id.clone()) {
    Some(_) => true,
    std::option::Option::None => false,
},
    std::option::Option::None => false,
}))
}

pub fn dag_round_trip_trivia_fidelity_resolved() -> bool {
    (((dag_whitespace_fidelity() == Rc::new(FidelityDisposition::DeclaredNormalized {
    feature: DagTriviaNormalization::DagWhitespaceDeclaredNormalized,
})) && (dag_line_comment_fidelity() == Rc::new(FidelityDisposition::FailClosed {
    feature: DagTriviaNormalization::DagLineCommentFailClosed,
}))) && (dag_block_comment_fidelity() == Rc::new(FidelityDisposition::FailClosed {
    feature: DagTriviaNormalization::DagBlockCommentFailClosed,
})))
}

pub fn dag_round_trip_authorities_ready() -> bool {
    {
        let lm = dag_language_model();
((dag_round_trip_lex_ready() && dag_round_trip_grammar_ready(lm)) && dag_round_trip_trivia_fidelity_resolved())
}
}

pub fn dag_surface_identity_is_top_level_item(id: std::string::String) -> bool {
    crate::std_algebra::fold_list(dag_grammar_top_level_item_productions(), false, |acc, production| (acc.clone() || match crate::v2_std_grammar::node_atom_identity_optional(production.emitted.clone()) {
    Some(emitted) => (emitted.clone() == id.clone()),
    std::option::Option::None => false,
}))
}

